const rows = $input.first().json.data;
const step = rows.find(r => r[0] === '2I');
if (!step) throw new Error('Step 2I not found');
return [{
  json: {
    step_id: step[0],
    step_name: step[1],
    model: step[2],
    temperature: parseFloat(step[3]) || 0.2,
    max_tokens: parseInt(step[4]) || 2500,
    system_prompt: step[6],
    user_prompt: step[7]
  }
}];

const cfg = $input.first().json;
const input = $input.first().json;
let user = cfg.user_prompt;
user = user.replace(/{{keyword}}/g, input.keyword || '');
user = user.replace(/{{article}}/g, input.article || '');
return [{
  json: {
    model: cfg.model,
    temperature: cfg.temperature,
    max_tokens: cfg.max_tokens,
    system_prompt: cfg.system_prompt,
    user_prompt: user,
    keyword: input.keyword
  }
}];

const resp = $input.first().json;
const content = resp.content || '';
let parsed = {};
try {
  parsed = JSON.parse(content);
} catch (e) {
  const m = content.match(/```json\n?([\s\S]*?)\n?```/);
  if (m) try { parsed = JSON.parse(m[1]); } catch (e2) { parsed = { raw_output: content }; }
  else parsed = { raw_output: content };
}

const ee = parsed.eeat || {};
const hcu = parsed.hcu || {};
const eav = parsed.eav || {};

// Calculate overall score
const eeScore = ee.score || 0;
const hcuScore = hcu.score || 0;
const eavScore = eav.score || 0;
const overall = (eeScore * 0.35) + (hcuScore * 0.40) + (eavScore * 0.25);

return [{
  json: {
    evaluator: parsed,
    ee_score: eeScore,
    hcu_score: hcuScore,
    eav_score: eavScore,
    overall_score: Math.round(overall),
    pass: overall >= 70,
    keyword: $input.first().json.keyword,
    step: '2I',
    input_tokens: resp.input_tokens || 0,
    output_tokens: resp.output_tokens || 0,
    output_json: JSON.stringify(parsed)
  }
}];

return [{
  json: {
    evaluator: $input.first().json.evaluator,
    overall_score: $input.first().json.overall_score,
    pass: true,
    keyword: $input.first().json.keyword,
    step: '2I',
    status: 'done'
  }
}];

return [{
  json: {
    evaluator: $input.first().json.evaluator,
    overall_score: $input.first().json.overall_score,
    pass: false,
    keyword: $input.first().json.keyword,
    step: '2I',
    status: 'needs_retry'
  }
}];
